-- Import customer/product commercial configurations.
-- Matching removes punctuation/spaces and compares lowercase names.
-- This catches harmless naming differences without guessing mappings.


insert into public.customer_products (customer_id, product_id, product_name_original, payment_term, incoterm, place_of_delivery, product_match_status)
values ((select c.id from public.customers c where c.name = 'Aamal Al Majad Industry Co' limit 1), (select p.id from public.products p where lower(regexp_replace(trim(p.name), '[^a-zA-Z0-9]+', '', 'g')) = lower(regexp_replace(trim('Polyol (Actcol LR00)'), '[^a-zA-Z0-9]+', '', 'g')) order by p.name limit 1), 'Polyol (Actcol LR00)', '50% Advance & 50% against 60 days from B/L Date', 'CIF Riyadh Dry Port', 'Riyadh Dry Port', case when (select p.id from public.products p where lower(regexp_replace(trim(p.name), '[^a-zA-Z0-9]+', '', 'g')) = lower(regexp_replace(trim('Polyol (Actcol LR00)'), '[^a-zA-Z0-9]+', '', 'g')) order by p.name limit 1) is null then 'unmatched' else 'matched' end)
on conflict (customer_id, product_name_original, payment_term, incoterm, place_of_delivery)
do update set product_id = excluded.product_id, product_match_status = excluded.product_match_status;
